/// <summary>
/// DebuC 22.09.23
/// </summary>
class NDXJobMangerJobsClass
{
    const int defaultInt = -1;

    NDXJobManagerJobId  jobManagerJobId;
    NDXJobManagerJobs   jobManagerJobs;

    //--> 1.1: NDX/PAFFH/NDX_TASK1235003633/12.12.2014
    NoYes               jobManagerProtFileActivate;
    NoYes               jobManagerProtFileWrite;
    str 100             jobManagerProtFilePath;
    str 20              jobManagerProtFileName;

}

Method.Source:
/// <summary>
/// DebuC 22.09.23
/// </summary>
void closeFileToWrite()
{
    if(jobManagerProtFileWrite == NoYes::Yes)
    {
        Info(strfmt('NXD5030', NDXHelperCommon::seconds2Str()));       // [%1] Ende Protokollierung
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "DS_Count">int</param>
/// <param name = "DS_new">int</param>
/// <param name = "DS_changed">int</param>
/// <param name = "lThread">boolean</param>
void ende(int DS_Count = defaultInt,
      int DS_new = defaultInt,
      int DS_changed = defaultInt,
      boolean lThread = true)
{
    NDXJobManagerJobs lNDX_JobManagerJobs;
    ;
    if (jobManagerProtFileActivate == NoYes::Yes)
    {
        lNDX_JobManagerJobs = jobManagerJobs.ende(DS_Count, DS_new, DS_changed, lThread);
        select jobManagerJobs where jobManagerJobs.RecId == lNDX_JobManagerJobs.RecId;
        if(jobManagerProtFileWrite == NoYes::Yes)
        {
            Info(strfmt('NDX:NDXEnd', NDXHelperCommon::seconds2Str()));       // [%1] Ende
        }
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_jobManagerJobId">NDXJobManagerJobId</param>
protected void new(NDXJobManagerJobId _jobManagerJobId)
{
    NDXUmsatzParameters    nDX_UmsatzParameters;
    ;
    //--> 1.1: NDX/PAFFH/NDX_TASK1235003633/12.12.2014
    nDX_UmsatzParameters = NDXUmsatzParametersGlobal::findParametersMaster();
    jobManagerProtFileActivate  = nDX_UmsatzParameters.JobManagerProtActivate;
    jobManagerProtFileWrite     = nDX_UmsatzParameters.JobManagerProtFileWrite;
    jobManagerProtFilePath      = nDX_UmsatzParameters.JobManagerProtFilePath;
    jobManagerProtFileName      = nDX_UmsatzParameters.JobManagerProtFileName;
    if (!jobManagerProtFilePath                   &&
    jobManagerProtFileActivate  == NoYes::Yes &&
    jobManagerProtFileWrite     == NoYes::Yes)
    {

        Warning('NXD5027');                    // Jobmanager - Protokollpfad wurde nicht festgelegt. Protokollierung wird deaktiviert!
        jobManagerProtFileActivate = NoYes::No;
        jobManagerProtFileWrite    = NoYes::No;
    }
    if (!jobManagerProtFileName                   &&
    jobManagerProtFileActivate  == NoYes::Yes &&
    jobManagerProtFileWrite     == NoYes::Yes)
    {

        Warning('NXD5028');                    // Jobmanager - Protokollname wurde nicht festgelegt. Protokollierung wird deaktiviert!
        jobManagerProtFileActivate = NoYes::No;
        jobManagerProtFileWrite    = NoYes::No;
    }
    //<-- NDX/PAFFH/NDX_TASK1235003633/12.12.2014

    jobManagerJobId = _jobManagerJobId;
    if (jobManagerProtFileActivate)
    {
        jobManagerJobs  = NDXJobManagerJobs::find(jobManagerJobId);
    }
}

/// <summary>
/// DebuC 27.02.24
/// </summary>
/// <param name = "_jobManagerJobId">NDXJobManagerJobId</param>
/// <returns>NDXJobMangerJobsClass</returns>
static NDXJobMangerJobsClass construct(NDXJobManagerJobId _jobManagerJobId)
{
    NDXJobMangerJobsClass jobManagerJobsClass = new NDXJobMangerJobsClass(_jobManagerJobId);

    return jobManagerJobsClass;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "lInit">boolean</param>
void openFileToWrite(boolean lInit = false)
{
    ;

    if (jobManagerProtFileWrite == NoYes::Yes)
    {

        if (lInit)
        {
            Info(strfmt('NXD5029', NDXHelperCommon::seconds2Str()));       // [%1] Start Protokollierung
        }
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "action">str</param>
/// <param name = "kennung">str</param>
/// <param name = "DSCount">int</param>
/// <param name = "DSnew">int</param>
/// <param name = "DSchanged">int</param>
/// <param name = "lThread">boolean</param>
void setAction(str action, str kennung,
           int DSCount   = defaultInt,
           int DSnew     = defaultInt,
           int DSchanged = defaultInt,
           boolean lThread = true)
{
    NDXJobManagerJobs lNDX_JobManagerJobs;
    ;
    if (jobManagerProtFileActivate == NoYes::Yes)
    {
        lNDX_JobManagerJobs = jobManagerJobs.setAction(action, kennung, DSCount, DSnew, DSchanged, lThread);
        select jobManagerJobs where jobManagerJobs.RecId == lNDX_JobManagerJobs.RecId;
        if (jobManagerProtFileWrite == NoYes::Yes)
        {
            Info(strfmt('NXD5032', NDXHelperCommon::seconds2Str(), action, kennung));      // [%1] Action [%2] Kennung [%3]
        }
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "action">str</param>
/// <param name = "kennung">str</param>
/// <param name = "lThread">boolean</param>
void start(str action = '', str kennung = '', boolean lThread = true)
{
    NDXJobManagerJobs lNDX_JobManagerJobs;
    ;
    if (jobManagerProtFileActivate == NoYes::Yes)
    {
        lNDX_JobManagerJobs = jobManagerJobs.start(action, kennung, lThread);
        select jobManagerJobs where jobManagerJobs.RecId == lNDX_JobManagerJobs.RecId;
        if (jobManagerProtFileWrite == NoYes::Yes)
        {
            Info(strfmt('NXD5033', NDXHelperCommon::seconds2Str(), action, kennung));      // [%1] Start [%2] Kennung [%3]
        }
    }
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_jobManagerJobs">NDXJobManagerJobs</param>
/// <returns>NDXJobManagerJobs</returns>
server static NDXJobManagerJobs ThreadExecute_Insert(NDXJobManagerJobs _jobManagerJobs)
{
    NDXJobManagerJobs      nDX_JobManagerJobs;
    ;

    nDX_JobManagerJobs = _jobManagerJobs;
    try
    {
        ttsbegin;
        nDX_JobManagerJobs.selectForUpdate(true);
        nDX_JobManagerJobs.insert();
        ttscommit;
    }
    catch
    {
        Error(strfmt("@NDX:NDXRecordInJobManagerJobsNotAdded", nDX_JobManagerJobs.RecId));    // DS in NDX_JobManagerJobs [%1] konnte nicht angefügt werden!
        return null;
    }
    return nDX_JobManagerJobs;
}

/// <summary>
/// DebuC 22.09.23
/// </summary>
/// <param name = "_jobManagerJobs">NDXJobManagerJobs</param>
server static void ThreadExecute_Update(NDXJobManagerJobs _jobManagerJobs)
{
    #OCCRetryCount
    NDXJobManagerJobs      nDX_JobManagerJobs;
    NDXJobManagerJobs      nDX_JobManagerJobs2;
    ;
    nDX_JobManagerJobs = _jobManagerJobs;
    try
    {
        ttsbegin;
        //--> NDX/PAFFH/NDX_TASK1235003759/10.11.2014
        //select forUpdate nDX_JobManagerJobs2 where nDX_JobManagerJobs2.RecId == nDX_JobManagerJobs.RecId;
        select firstonly pessimisticlock nDX_JobManagerJobs2 where nDX_JobManagerJobs2.RecId == nDX_JobManagerJobs.RecId;
        //<-- NDX/PAFFH/NDX_TASK1235003759/10.11.2014
        buf2Buf(nDX_JobManagerJobs, nDX_JobManagerJobs2);
        nDX_JobManagerJobs2.update();
        ttscommit;
    }
    catch (Exception::Deadlock)
    {
        if (xSession::currentRetryCount() >= #RetryNum)
        {
            throw Exception::Deadlock;
        }
        else
        {
            retry;
        }
    }
    catch (Exception::UpdateConflict)
    {
        //if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                throw Exception::UpdateConflictNotRecovered;
            }
            else
            {
                retry;
            }
        }
        //else
        //    throw Exception::UpdateConflict;
    }
    catch
    {
        Error(strfmt("@NDX:NDXJobManagerJobsNotWritten", nDX_JobManagerJobs2.RecId));     // DS in NDX_JobManagerJobs [%1] konnte nicht geschrieben werden!
    }
}
